package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import org.springframework.stereotype.Component;

/** Three disjoint B25 contracts. An authored classification is not regulatory approval. */
@Component public final class RegistrationLifecycleSchema {
 public static final String IVD="IVD_REGISTRATION", CHANGE="CHANGE_REGISTRATION", RENEWAL="RENEWAL_REGISTRATION";
 public static final Map<String,String> PREFIXES=Map.of(IVD,"ivd-registration-v1\n",CHANGE,"change-registration-v1\n",RENEWAL,"renewal-registration-v1\n");
 private final JsonMapper json=JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,DeserializationFeature.FAIL_ON_TRAILING_TOKENS,DeserializationFeature.FAIL_ON_MISSING_CREATOR_PROPERTIES).propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).build();
 public record Source(String key,PermissionProtocol.Basis source,String rightsRevision,DatasetProtocol.EvidenceRef evidence,String literal,String nature){}
 public record Fact(String text,List<String> sourceKeys){}
 public record DirectoryItem(String key,String title,String applicability,Fact basis,List<String> evidenceSourceKeys){}
 public record ConsistencyValue(String key,String field,String model,String condition,String unit,String value,String sourceKey){}
 public record Body(String key,String nodeId,String sectionId,List<String> entityKeys,JsonNode content,List<String> sourceKeys){public String text(){return ClinicalEvaluationSchema.projection(content);}}
 public record ApplicabilityDecision(String scenarioKind,String directoryKey,String outcome,List<String> evidenceSourceKeys){}
 public record Catalogue(String scenarioKind,String productCategory,String authority,String edition,String effectiveDate,List<CatalogueItem> items){}
 public record CatalogueItem(String key,String title){}
 public record PathDecision(String scenarioKind,String productCategory,String outcome,String catalogueSourceKey,String templateVersion,String historySourceKey){}
 public record History(String certificateNumber,String originalSourceKey,List<String> changeSourceKeys,List<String> currentSourceKeys){}
 public record HistoryApproval(String certificateNumber,String originalSourceKey,List<String> changeSourceKeys,List<String> currentSourceKeys,String outcome){}
 public record ChangeItem(String key,Fact before,Fact after,Fact reason,Fact models,Fact riskImpact,Fact validation,Fact clinicalImpact,Fact instructionsImpact,Fact labelImpact,Fact qualitySystemImpact,List<String> beforeDocumentSourceKeys,List<String> afterDocumentSourceKeys){}
 public record RenewalDecision(String conditionKey,String group,String outcome,List<String> criterionSourceKeys,List<String> evidenceSourceKeys){}
 public record RenewalCondition(String key,String group,String outcome,Fact criterion,Fact assessment,List<String> evidenceSourceKeys){}
 public interface Selection {String schemaVersion();String scenarioKind();List<String> sectionIds();List<Source> sources();PermissionProtocol.Basis templateVersion();String productCategory();String catalogueSourceKey();Fact pathDecision();List<DirectoryItem> directory();List<Body> body();List<ConsistencyValue> consistency();}
 public record IvdSelection(String schemaVersion,String scenarioKind,List<String> sectionIds,List<Source> sources,PermissionProtocol.Basis templateVersion,String productCategory,String catalogueSourceKey,Fact pathDecision,List<DirectoryItem> directory,List<Body> body,List<ConsistencyValue> consistency,Fact intendedUse,Fact reagentClassification,List<String> analyticalEvidenceSourceKeys,List<String> clinicalEvidenceSourceKeys) implements Selection {}
 public record ChangeSelection(String schemaVersion,String scenarioKind,List<String> sectionIds,List<Source> sources,PermissionProtocol.Basis templateVersion,String productCategory,String catalogueSourceKey,Fact pathDecision,List<DirectoryItem> directory,List<Body> body,List<ConsistencyValue> consistency,History history,String historySourceKey,List<ChangeItem> changes) implements Selection {}
 public record RenewalSelection(String schemaVersion,String scenarioKind,List<String> sectionIds,List<Source> sources,PermissionProtocol.Basis templateVersion,String productCategory,String catalogueSourceKey,Fact pathDecision,List<DirectoryItem> directory,List<Body> body,List<ConsistencyValue> consistency,History history,String historySourceKey,List<RenewalCondition> conditions) implements Selection {}
 public static boolean supportsKind(String kind){return PREFIXES.containsKey(kind);}public static boolean supportsDefinition(String d){return PREFIXES.values().stream().anyMatch(d::startsWith);}
 public Selection read(JsonNode n)throws Exception{try{
  String kind=n.required("scenario_kind").asText();Selection s=switch(kind){case IVD -> json.treeToValue(n,IvdSelection.class);case CHANGE -> json.treeToValue(n,ChangeSelection.class);case RENEWAL -> json.treeToValue(n,RenewalSelection.class);default -> throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);};
  if(!"1.0.0".equals(s.schemaVersion())||s.sectionIds().isEmpty()||s.sectionIds().size()>128||s.sources().size()>512||s.directory().size()>512||s.body().size()>1024||s.consistency().size()>1024)bad();unique(s.sectionIds());s.sectionIds().forEach(WireValues::uuid);WireValues.uuid(s.templateVersion().version_id());WireValues.hash(s.templateVersion().content_sha256());text(s.productCategory());
  var keys=new HashSet<String>();for(var x:s.sources()){text(x.key());if(!keys.add(x.key())||!Set.of("CATALOGUE","RULE","APPROVED_DECISION","ORIGINAL_CERTIFICATE","CHANGE_RECORD","CURRENT_DOCUMENT","VALIDATION","CLINICAL","ANALYTICAL","STANDARD_UPDATE","CONTINUING_STUDY","ATTACHMENT").contains(x.nature()))bad();WireValues.uuid(x.source().version_id());WireValues.hash(x.source().content_sha256());WireValues.uuid(x.rightsRevision());new TaskSourceReadReceiptSchema(new PermissionSchema()).evidence(tree(x.evidence()));if(!x.source().version_id().equals(x.evidence().sourceVersion()))bad();text(x.literal());}
  optionalRef(s.catalogueSourceKey(),keys);fact(s.pathDecision(),keys);var entities=new HashSet<String>(List.of("PATH"));
  for(var x:s.directory()){text(x.key());text(x.title());if(Set.of("PATH","HISTORY","IVD_PRODUCT").contains(x.key())||!entities.add(x.key())||!Set.of("REQUIRED","NOT_APPLICABLE","UNKNOWN").contains(x.applicability()))bad();fact(x.basis(),keys);refs(x.evidenceSourceKeys(),keys);}
  if(s instanceof IvdSelection i){entities.add("IVD_PRODUCT");fact(i.intendedUse(),keys);fact(i.reagentClassification(),keys);refs(i.analyticalEvidenceSourceKeys(),keys);refs(i.clinicalEvidenceSourceKeys(),keys);}
  if(s instanceof ChangeSelection c){history(c.history(),c.historySourceKey(),keys);entities.add("HISTORY");if(c.changes().size()>256)bad();for(var x:c.changes()){text(x.key());if(!entities.add(x.key()))bad();for(var f:changeFacts(x))fact(f,keys);refs(x.beforeDocumentSourceKeys(),keys);refs(x.afterDocumentSourceKeys(),keys);}}
  if(s instanceof RenewalSelection r){history(r.history(),r.historySourceKey(),keys);entities.add("HISTORY");if(r.conditions().size()>256)bad();for(var x:r.conditions()){text(x.key());if(!entities.add(x.key())||!Set.of("CERTIFICATE_VALIDITY","MANDATORY_STANDARD_UPDATE","CONTINUING_STUDY","CHANGED_TECHNICAL_REQUIREMENTS","OTHER").contains(x.group())||!Set.of("SATISFIED","NOT_APPLICABLE","UNSATISFIED","UNKNOWN").contains(x.outcome()))bad();fact(x.criterion(),keys);fact(x.assessment(),keys);refs(x.evidenceSourceKeys(),keys);}}
  var comparisons=new HashSet<String>();for(var c:s.consistency()){text(c.key());text(c.field());optional(c.model());optional(c.condition());optional(c.unit());optional(c.value());if(!comparisons.add(c.key())||!keys.contains(c.sourceKey()))bad();}
  var bodies=new HashSet<String>();var nodes=new HashSet<String>();for(var b:s.body()){text(b.key());WireValues.uuid(b.nodeId());if(!bodies.add(b.key())||!nodes.add(b.nodeId())||!s.sectionIds().contains(b.sectionId())||b.content()==null||!b.content().isObject()||!Set.of("TEXT","TABLE","IMAGE","FORMULA").contains(b.content().path("kind").asText()))bad();refs(b.entityKeys(),entities);refs(b.sourceKeys(),keys);}
  return s;
 }catch(IllegalArgumentException|NullPointerException e){throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}}
 static List<Fact> changeFacts(ChangeItem x){return List.of(x.before(),x.after(),x.reason(),x.models(),x.riskImpact(),x.validation(),x.clinicalImpact(),x.instructionsImpact(),x.labelImpact(),x.qualitySystemImpact());}
 private static void history(History h,String source,Set<String> keys){optionalRef(source,keys);optional(h.certificateNumber());optionalRef(h.originalSourceKey(),keys);refs(h.changeSourceKeys(),keys);refs(h.currentSourceKeys(),keys);}
 public ApplicabilityDecision applicabilityDecision(String literal)throws Exception{return json.readValue(literal,ApplicabilityDecision.class);}public Catalogue catalogue(String literal)throws Exception{return json.readValue(literal,Catalogue.class);}public PathDecision decision(String literal)throws Exception{return json.readValue(literal,PathDecision.class);}public RenewalDecision renewalDecision(String literal)throws Exception{return json.readValue(literal,RenewalDecision.class);}public HistoryApproval historyApproval(String literal)throws Exception{return json.readValue(literal,HistoryApproval.class);}
 public JsonNode tree(Object v){return json.valueToTree(v);}
 public Selection definition(String d)throws Exception{for(var entry:PREFIXES.entrySet())if(d.startsWith(entry.getValue())){var s=read(json.readTree(d.substring(entry.getValue().length())));if(!entry.getKey().equals(s.scenarioKind()))bad();return s;}throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}
 public String definition(JsonNode n)throws Exception{var s=read(n);String d=PREFIXES.get(s.scenarioKind())+new String(ContentReadAuthorization.canonicalBytes(tree(s)),java.nio.charset.StandardCharsets.UTF_8);if(d.length()>200000)bad();return d;}
 public void author(JsonNode a)throws Exception{String d=a.required("specification").required("INPUTS").required("definition").asText();if(!supportsDefinition(d))return;var s=definition(d);var roots=new HashSet<PermissionProtocol.Basis>();for(var r:a.required("specification").required("APPLICABLE_KNOWLEDGE").required("evidence"))roots.add(new PermissionProtocol.Basis(r.required("version_id").asText(),r.required("content_sha256").asText()));for(var x:s.sources())if(!roots.contains(x.source())||!a.required("project_id").asText().equals(x.evidence().projectId()))bad();boolean template=false;for(var ref:a.required("applicability").required("templates"))if(tree(s.templateVersion()).equals(ref))template=true;if(!template)bad();}
 private static void fact(Fact f,Set<String> keys){optional(f.text());refs(f.sourceKeys(),keys);}private static void optionalRef(String s,Set<String> keys){optional(s);if(!s.isEmpty()&&!keys.contains(s))bad();}
 private static void refs(List<String> x,Set<String> keys){if(x==null||x.size()>512||!keys.containsAll(x))bad();unique(x);}private static void unique(List<String> x){if(new HashSet<>(x).size()!=x.size())bad();}private static void text(String x){ProjectSchema.text(x,16000);}private static void optional(String x){if(x==null||x.length()>16000)bad();}private static void bad(){throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}
}
